#!/bin/sh
#
# mkboot.sh: generate the bootstrap C bundle of patsopt in this directory (run by `make -C src CBOOT`).
#
# Needs a working patsopt ($PATSOPT, default: the one of src/Makefile), python3 (the arena encodings of the
# compiler are generated by ../../utils/arenagen) and a C compiler for nothing else: the C code is only generated.
# Output (everything but this script, Makefile, README and .gitignore is generated and ignored by git):
#   *_dats.c, pats_error_sats.c, pats_runtime_ats1.c,
#   libatsopt_ext.c                                    C code that does not depend on the integer kind
#   gmpknd/*.c  intknd/*.c                              the modules that do (pats_intinf, pats_lintprgm_myint, pats_constraint3_solve)
#   inc/                                                the headers the C code includes (ccomp/runtime, prelude/CATS, libats/CATS, src/*.cats)
#   modules.mk                                          the lists of the objects (included by Makefile)
#
set -e
here=`cd \`dirname $0\` && pwd`
src=`cd $here/.. && pwd`
: ${PATSHOME:=`cd $src/.. && pwd`}
: ${MAKE:=make}
: ${JOBS:=`nproc 2>/dev/null || echo 4`}
PATSHOME=`cd $PATSHOME && pwd`
export PATSHOME
cd $src

PATSOPT_ARG=
[ -n "$PATSOPT" ] && PATSOPT_ARG="PATSOPT=$PATSOPT"

rm -rf CBOOT/gen_gmpknd CBOOT/gen_intknd CBOOT/gmpknd CBOOT/intknd CBOOT/inc CBOOT/*.c CBOOT/modules.mk
for k in gmpknd intknd; do
  echo "CBOOT: generating the C code, C3NSTRINTKND=$k"
  $MAKE -s -j$JOBS $PATSOPT_ARG C3NSTRINTKND=$k P2OBJDIR=CBOOT/gen_$k bootc
done

mkdir CBOOT/gmpknd CBOOT/intknd CBOOT/inc
# the time stamp of the generated C code would make the bundle differ from run to run
for k in gmpknd intknd; do
  for f in CBOOT/gen_$k/*.c; do sed '/^\*\* The starting compilation time is: [0-9]/d' $f > $f.tmp && mv $f.tmp $f; done
done
common=; gmp=; int=
for f in `cd CBOOT/gen_gmpknd && ls *.c`; do
  if cmp -s CBOOT/gen_gmpknd/$f CBOOT/gen_intknd/$f; then
    mv CBOOT/gen_gmpknd/$f CBOOT/$f; common="$common $f"
  else
    mv CBOOT/gen_gmpknd/$f CBOOT/gmpknd/$f; mv CBOOT/gen_intknd/$f CBOOT/intknd/$f
    gmp="$gmp $f"; int="$int $f"
  fi
done
rm -rf CBOOT/gen_gmpknd CBOOT/gen_intknd
# the hand-written run-time of the driver
cp pats_runtime_ats1.c CBOOT/pats_runtime_ats1.c; common="$common pats_runtime_ats1.c"
# the C part of libatsopt (the C API of utils/libatsopt)
cp libatsopt_ext.c CBOOT/libatsopt_ext.c; common="$common libatsopt_ext.c"

# the headers: the closure of what the C files include (gcc -MM) from the repository, copied with the same relative paths
# (the files of src/ flat), so that the bundle is compiled with -Iinc -Iinc/ccomp/runtime only
mkdir -p CBOOT/inc/ccomp/runtime
cp -L $PATSHOME/ccomp/runtime/*.h $PATSHOME/ccomp/runtime/*.c CBOOT/inc/ccomp/runtime/
: ${CC:=gcc}
for f in CBOOT/*.c CBOOT/gmpknd/*.c CBOOT/intknd/*.c; do
  $CC -MM -std=c99 -D_XOPEN_SOURCE -D_GNU_SOURCE -DATS_MEMALLOC_LIBC -include alloca.h \
    -I$PATSHOME -I$PATSHOME/ccomp/runtime -I$src $f | tr ' \\' '\n\n' | grep -v '^$' | grep '/' | grep -v '^/usr'
done | sort -u > CBOOT/gen_deps.txt
while read d; do
  d=`cd \`dirname $d\` && pwd`/`basename $d`
  case $d in
    $src/CBOOT/*) ;;
    $src/*) cp -L $d CBOOT/inc/`basename $d` ;;
    $PATSHOME/*) r=${d#$PATSHOME/}; mkdir -p CBOOT/inc/`dirname $r`; cp -L $d CBOOT/inc/$r ;;
  esac
done < CBOOT/gen_deps.txt
rm -f CBOOT/gen_deps.txt

{
  echo "# generated by mkboot.sh: the C files of the bundle"
  echo "COMMON_C=$common"
  echo "GMPKND_C=$gmp"
  echo "INTKND_C=$int"
} > CBOOT/modules.mk
echo "CBOOT: done: `echo $common | wc -w` common files, `echo $gmp | wc -w` per integer kind, headers in CBOOT/inc"
echo "CBOOT: build the compiler with: make -C src/CBOOT   (KIND=intknd for a build without gmp)"
